#!/usr/bin/env node
/*
 * Re-add this package's own ProGuard rules after code generation.
 *
 * `android/proguard-rules.pro` is generated by uniffi-bindgen-react-native from
 * a template (`crates/ubrn_cli/templates/jsi/android/proguard-rules.pro`) and is
 * rewritten on every `yarn generate:android`, so a rule added by hand survives
 * exactly until the next regeneration. `android/build.gradle` is generated the
 * same way, which rules out the other obvious approach of keeping the rules in a
 * separate file and adding it to `consumerProguardFiles`.
 *
 * So append them here instead, as a post-generation step - the same shape as
 * scripts/sort-uniffi-calls.js, and wired into the same `generate:*:android`
 * scripts.
 *
 * These rules are deliberately NOT contributed to ubrn's template: the JNA rules
 * it generates apply to every uniffi module, whereas rustls-platform-verifier is
 * a matrix-sdk-ffi dependency and has no business in a generic template.
 *
 * Idempotent - running it twice is a no-op.
 */

const fs = require('fs');
const path = require('path');

const PROGUARD_FILE_PATH = 'android/proguard-rules.pro';

// Matched to decide whether the rules are already present. Any line unique to
// the block below would do; the rule itself is the least likely to be reworded.
const MARKER = '-keep class org.rustls.platformverifier.** { *; }';

const RULES = `# matrix-sdk-ffi validates TLS certificates through the \`rustls-platform-verifier\`
# crate, whose Rust half reaches this JVM half by name over JNI:
#
#   FindClass("org/rustls/platformverifier/CertificateVerifier")
#
# No Java or Kotlin code references these classes, so R8 sees an unused package
# and deletes it. Nothing fails at build time; the app installs, starts, and then
# every HTTPS request fails, because the verifier cannot be constructed:
#
#   java.lang.ClassNotFoundException: Didn't find class
#   "org/rustls/platformverifier/CertificateVerifier"
#
# In this package's example that surfaces as a homeserver returning
# supportsOidcLogin: false / supportsPasswordLogin: false rather than as an
# error, which makes it easy to mistake for a server-side answer.
#
# \`verifier_full_name\` in the crate's build script pins the class path, so these
# names cannot be renamed either - hence -keep rather than -keepnames.
${MARKER}
`;

function appendProguardRules() {
  const filePath = path.resolve(PROGUARD_FILE_PATH);

  if (!fs.existsSync(filePath)) {
    console.error(`Error: File not found: ${filePath}`);
    process.exit(1);
  }

  const contents = fs.readFileSync(filePath, 'utf8');

  if (contents.includes(MARKER)) {
    console.log('append-proguard-rules: rules already present, nothing to do');
    return;
  }

  // The generated file has no trailing newline, so normalise before appending
  // rather than assuming either shape.
  const separator = contents.endsWith('\n') ? '\n' : '\n\n';
  fs.writeFileSync(filePath, `${contents}${separator}${RULES}`);

  console.log(`append-proguard-rules: added rustls-platform-verifier rules to ${PROGUARD_FILE_PATH}`);
}

appendProguardRules();
